def overlap_minutes(meetings: list[list[int]], k: int) -> int:
    if k > len(meetings):
        return 0

    events = []
    for start, end in meetings:
        if start < end:
            events.append((start, 1))
            events.append((end, -1))
    events.sort()

    total = 0
    active = 0
    previous = 0

    for timestamp, change in events:
        if active >= k:
            total += timestamp - previous
        active += change
        previous = timestamp

    return total
